// Minimal Local HTMX implementation (Replaced with actual HTMX for production)
// For the sake of this pure local setup, we are using a lightweight custom script.
document.addEventListener("DOMContentLoaded", function() {
    document.body.addEventListener('htmx:afterSwap', function(evt) {
        console.log("HTMX: DOM updated", evt.detail.target.id);
    });
});